const request = $('PUT /patients/:id').first().json;
const id = request.params.id;
const body = request.body ?? {};

const patients = $input.all().map(item => item.json);

const existing = patients.find(
  patient => patient.patient_id === id && !patient.deleted_at
);

if (!existing) {
  return [{
    json: {
      found: false,
      statusCode: 404,
      data: null,
      error: {
        code: 'NOT_FOUND',
        message: 'Patient not found'
      }
    }
  }];
}

const allowedFields = [
  'first_name',
  'last_name',
  'date_of_birth',
  'sex',
  'phone_number',
  'email',
  'address_line_1',
  'address_line_2',
  'city',
  'state',
  'zip_code',
  'insurance_provider',
  'insurance_member_id',
  'preferred_language',
  'emergency_contact_name',
  'emergency_contact_phone'
];

const update = {};

for (const field of allowedFields) {
  if (body[field] !== undefined) {
    update[field] = body[field];
  }
}

if (Object.keys(update).length === 0) {
  return [{
    json: {
      found: false,
      statusCode: 400,
      data: null,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'No valid fields provided for update'
      }
    }
  }];
}

// Normalize phone
if (update.phone_number !== undefined) {
  update.phone_number = String(update.phone_number).replace(/\D/g, '');

  if (!/^\d{10}$/.test(update.phone_number)) {
    return [{
      json: {
        found: false,
        statusCode: 400,
        data: null,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Phone number must contain exactly 10 digits'
        }
      }
    }];
  }
}

// Normalize state
if (update.state !== undefined) {
  update.state = String(update.state).trim().toUpperCase();

  if (!/^[A-Z]{2}$/.test(update.state)) {
    return [{
      json: {
        found: false,
        statusCode: 400,
        data: null,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'State must be a 2-letter abbreviation'
        }
      }
    }];
  }
}

// Validate ZIP
if (update.zip_code !== undefined) {
  update.zip_code = String(update.zip_code).trim();

  if (!/^\d{5}(-\d{4})?$/.test(update.zip_code)) {
    return [{
      json: {
        found: false,
        statusCode: 400,
        data: null,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid ZIP code'
        }
      }
    }];
  }
}

// Validate DOB
if (update.date_of_birth !== undefined) {
  const dob = String(update.date_of_birth).trim();

  if (!/^\d{4}-\d{2}-\d{2}$/.test(dob)) {
    return [{
      json: {
        found: false,
        statusCode: 400,
        data: null,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'date_of_birth must use YYYY-MM-DD format'
        }
      }
    }];
  }

  const dobDate = new Date(`${dob}T00:00:00Z`);
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);

  if (Number.isNaN(dobDate.getTime()) || dobDate > today) {
    return [{
      json: {
        found: false,
        statusCode: 400,
        data: null,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid or future date_of_birth'
        }
      }
    }];
  }

  update.date_of_birth = dob;
}

// Validate sex
if (
  update.sex !== undefined &&
  !['Male', 'Female', 'Other', 'Decline to Answer'].includes(update.sex)
) {
  return [{
    json: {
      found: false,
      statusCode: 400,
      data: null,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Invalid sex'
      }
    }
  }];
}

// Normalize emergency phone
if (update.emergency_contact_phone !== undefined && update.emergency_contact_phone !== null) {
  update.emergency_contact_phone = String(update.emergency_contact_phone).replace(/\D/g, '');

  if (!/^\d{10}$/.test(update.emergency_contact_phone)) {
    return [{
      json: {
        found: false,
        statusCode: 400,
        data: null,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Emergency contact phone must contain exactly 10 digits'
        }
      }
    }];
  }
}

return [{
  json: {
    found: true,
    patient_id: id,
    update,
    statusCode: 200
  }
}];
